registerRefData('nsw-cond-n-5432',{"id":5432,"pan":null,"ref":"49534/2016 S8.2 Review of Determination","address":"9 Bent Street Gosford Lot 1 Dp436706","description":"8.2(1)a - INTEGRATED Residential Flat Building Including 101 Units & 3 Levels of Basement Parking & the Demolition of Existing Structures on Site (RPP)","outcome":"approved","outcome_raw":"Approved","outcome_source":"planning_panels","determined":null,"notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSHCC-24!20201105T024143.722 GMT","sha256":"4228b93d00e63ccc543c07d3be27e748b3242de132e7ea4f1ed47a166591b390","pages":25,"layout":"numbered","n":10,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/5432.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/821a-integrated-residential-flat-building-including-101-units-3-levels-basement","lga":"CENTRAL COAST","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSHCC-24 - Central Coast Council - DA 49534/2016","stage":"general","stage_basis":"heading","page":4},{"label":"2","code":null,"number":"2","title":"","text":"PROPOSED DEVELOPMENT Residential Flat Building comprising 56 units and three (3) levels of\nbasement parking and the demolition of existing structures on site\n(Integrated Development)","stage":"general","stage_basis":"heading","page":4},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 7-11 Bent Street, Gosford","text":"","stage":"general","stage_basis":"heading","page":4},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Albany Investments Aust Pty Ltd","text":"","stage":"general","stage_basis":"heading","page":4},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT General development over $20 million (DA lodged prior to 1 March 2018)","stage":"general","stage_basis":"heading","page":4},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n Local Government Act 1993\n Roads Act 1993\n Rural Fires Act 1997 & Planning for Bushfire Protection\n Environmental planning instruments:\no State Environmental Planning Policy (State and Regional\nDevelopment) 2011\no State Environmental Planning Policy No 55 - Remediation of Land\no State Environmental Planning Policy No 65 - Design Quality of\nResidential Apartment Development & Apartment Design Guide\no State Environmental Planning Policy (Coastal Management) 2018\no State Environmental Planning Policy (Building Sustainability Index:\nBASIX) 2004\no Gosford Local Environmental Plan 2014\no Central Coast Regional Plan 2036\n Draft environmental planning instruments:\no Draft Central Coast Local Environmental Plan 2018\n Development control plans:\no Gosford Development Control Plan 2013\n Planning agreements: Nil\n Provisions of the Environmental Planning and Assessment Regulation\n2000:\n Coastal zone management plan: Nil\n The likely impacts of the development, including environmental\nimpacts on the natural and built environment and social and economic\nimpacts in the locality\n The suitability of the site for the development\n Any submissions made in accordance with the Environmental Planning\nand Assessment Act 1979 or regulations\n The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":4},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n Council assessment report: 15 October 2020\n Addendum Council assessment report: 27 October 2020\n Written submissions during public exhibition\n Plans prepared by ADG Architects, Revision F","stage":"general","stage_basis":"heading","page":4},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n Briefing: 13 May 2020\no Panel members: Alison McCabe (Chair), Sandra Hutton, Juliet\nGrant, Kyle MacGregor and Chris Burke\no Council assessment staff: Chris Ross, Erin Murphy, Ailsa\nPredergast, John Noakes and Andrew Roach\n Site visits:\no Alison McCabe (Chair): 9 September 2020\no Sandra Hutton: 27 April 2020\no Juliet Grant: 24 May 2020\n Briefing to discuss council’s recommendation: 21 October 2020\no Panel members: Alison McCabe (Chair), Sandra Hutton, Jane\nSmith and Jeff Sundstrom\no Council assessment staff: Ailsa Prendergast, John Noakes and\nChris Ross\n Submitter briefing: 21 October 2020\no Panel members: Alison McCabe (Chair), Sandra Hutton, Jane\nSmith and Jeff Sundstrom\no Council assessment staff: Ailsa Prendergast, John Noakes and\nChris Ross\no Submitters: Ian Kerr, Rosemarie Chad and Glenys Tate\n Applicant briefing: 21 October 2020\no Panel members: Alison McCabe (Chair), Sandra Hutton, Jane\nSmith and Jeff Sundstrom\no Council assessment staff: Ailsa Prendergast, John Noakes and\nChris Ross\no Applicant representatives: Shea Cullen, Peter Harb and Sarah\nHartley\n Final briefing to discuss council’s recommendation: 28 October 2020\no Panel members: Alison McCabe (Chair), Sandra Hutton, Jane\nSmith, Jeff Sundstrom and Juliet Grant\no Council assessment staff: Ailsa Prendergast, John Noakes and\nChris Ross","stage":"general","stage_basis":"heading","page":4},{"label":"9","code":null,"number":"9","title":"COUNCIL","text":"RECOMMENDATION Approval","stage":"general","stage_basis":"heading","page":5},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the council assessment report","text":"REGIONAL PLANNING PANEL\n(Hunter and Central Coast)\nThis consent does not operate until the following have been satisfied:\n1) The submission of the following to allow the applicant to gain permission to undertake inter-allotment\ndrainage works:\na) Creation of an easement to drain water minimum 1m wide over Lot 27 Sec 6 DP 1591, Lot 28 Sec 6 DP\n1591, & Lot B DP 338871 generally in accordance with the alignm ent indicated on the plan prepared\nby Barker Ryan Stewart, Plan No CC150124E1.19 Rev G dated 2/04/ 2019. Documentary evidence of\nthe creation of this required easement to drain water shall be submitted to Council\nb) Written permission to enter the site and construct the IAD syst em is to be obtained from the owners\nof each of the burdened properties listed above.\n2) All works to and within the Gertrude Extension road reserve are to be deleted from plans. Works are to\nbe undertaken through condition 2.6 of this consent.\n3) Detailed landscape plans prepared by a qualified landscape Architect are to be prepared to reflect the\ndraft landscape elements as shown on the plans provided for this review. The plans are to detail all\nspecies, plant stock sizes and planting/maintenance requirements.\nEvidence must be produced to the consent authority sufficient to enable it to be satisfied that above\nconditions have been complied within twelve (12) months of the date of this approval, otherwise this consent\nwill lapse.\nUpon compliance with the conditions of deferred commencement Council will issue an operative consent\n(including stamped plans) that is subject to the attached conditions.\n1.1. Approved Plans and Supporting Documents\nImplement the development substantially in accordance with the plans and supporting documents\nlisted below as submitted by the applicant and to which is affixed a Council stamp \"Development\nConsent\" unless modified by any following condition.\nArchitectural plans prepared by ADG Architects:\nDrawing Description Issue Date\nDA00 Cover sheet F 22.10.2020\nDA01 Site analysis E 22.10.2020\nDA02 Site plan F 22.10.2020\nDA03 Demolition plan and bulk excavation sections F 22.10.2020\nDA04 Basement 3 plan F 22.10.2020\nDA05 Basement 2 plan F 22.10.2020\nDA06 Basement 1 plan F 22.10.2020\nDA07 Lower ground plan F 22.10.2020\nDA08 Ground floor plan G 22.10.2020\nSCHEDULE 2\nDEFERRED COMMENCEMENT\n1.. PARAMETERS OF THIS CONSENT\nDA09 Level 1 plan F 22.10.2020\nDA10 Level 2 plan F 22.10.2020\nDA11 Level 3 plan F 22.10.2020\nDA12 Level 4 plan F 22.10.2020\nDA13 Level 5 plan F 22.10.2020\nDA14 Level 6 plan F 22.10.2020\nDA15 Level 7 plan F 22.10.2020\nDA16 Level 8 plan F 22.10.2020\nDA17 Level 9 plan F 22.10.2020\nDA18 Level 10 plan F 22.10.2020\nDA19 Roof Plan F 22.10.2020\nDA21 North & south elevation F 22.10.2020\nDA22 East & west ele vation F 22.10.2020\nDA23 Elevation Showing Outline of Previous Design F 22.10.2020\nDA24 Section F 22.10.2020\nDA26 Retaining Wall Sections F 22.10.2020\nDA27 Schedule of areas and SEPP 65 Compliance E 22.10.2020\nDA30 Shadow diagram F 22.10.2020\nDA31 Solar Access to Neigh bours POA and Proposed\nCommunal Open Space on June 21\nF 22.10.2020\nDA32 Street Montage F 22.10.2020\nDA40 Height Plane Diagram F 22.10.2020\nDA41 Shadows with Context F 22.10.2020\nSupporting Documentation\nDocument Prepared by Date / Issue ECM\nDocument No:\nApartment Design Guide\nCompliance Report and\nVerification Statement\nAnthony Kelly (registered\narchitect No.6999)\n10.20\nRev H\n14232038\nNoise Assessment Spectrum Ac oustics February 2016 26870218\nProposed road, driveway &\ndrainage\nDA plans Sheets 1 -19\nBarker Ryan Stewart 02.04.19\nRev G\n26832126\nTraffic & Parking Impact\nAssessment\nBarker Ryan Stewart 15.10.19\nRev 8\n25427054\nStormwater Management\nReport\nBarker Ryan Stewart 20.11.19\nRev 4\nECMD25427052\nWaste Management Plan Barker Ryan Stewart 05.05.20\nRev 9\n14241319\nBASIX Certificate number:\n713208M_05\nGradwell Consulting 27.08.20 14229260\nNatHERS Ceretificate Gradwell Consulting 27.08.20 14229262\nAssessor Certificate Gradwe ll Consulting 03.05.19 26829844\nArboricultural\nImpact assessment\nADVANCED TREESCAPE\nCONSULTING\n19.11.18 26540054\nFlora and Fauna Impact\nAssessment REF: GCC 15-778\nKeystone Ecological December 2015 26540053\nSurvey Plan Alan Bardsley 16.08.15 26540066\nBushfire Assessment Report\nAdvanced Bushfire\nPerformance Solutions\n01.11.19\nRev 6\n25427043\nDA Access Audit Assistive Technology\nAustralia\n21.12.18\nRev 1\n26540064\nGeotechnical Investigation A sset Geotechnical 09.10.15 26540062\nCrime Prevention through\nEnvironmental Design\nAssessment\nBarker Ryan Stewart 19.11.19\nRev 4\n25427047\nReference Set of Engineering Plans\nDocument Prepared by Date / Issue\nProposed Road, Driveway\nand Drainage DA Plans\nBaker Ryan Stewart\n150124E1.01-\n019 2/4/2019\nRev G\n1.2. Carry out all building works in accordance with the Building Code of Australia.\n1.3. Comply with the General Terms of Approval from the NSW Rural Fire Service, letter reference\nDA20191216001532-Original-1, dated 06 February 2020, as reproduced below:\nAsset Protection Zones\nThe intent of measures is to provide sufficient space and maintain reduced fuel loads so as to\nensure radiant heat levels of buildings are below critical limits and to prevent direct flame contact\nwith a building. To achieve this, the following conditions shall apply:\n1. At the commencement of building works, or the issue of a subdivision certificate (whichever\ncomes first) and in perpetuity, the entire property shall be managed as an Inner Protection Area\n(IPA) as outlined within section 4.1.3 and Appendix 5 of 'Planning for Bush Fire Protection 2006'\nand the NSW Rural Fire Service's document 'Standards for asset protection zones'.\n2. Prior to the issue of occupancy certificate the proposed landscaped area adjacent to Henry Parks\ndrive shall be completed in accordance with the “Ground Flood Landscape Plan 1 of 2” prepared\nby Xeriscapes dated 28.11.18, Drawing No.L101. and be managed in accordance with the same\nplan.\nWater and Utilities\nThe intent of measures is to provide adequate services of water for the protection of buildings\nduring and after the passage of a bush fire, and to locate gas and electricity so as not to contribute\nto the risk of fire to a building. To achieve this, the following conditions shall apply:\n3. Water, electricity and gas are to comply with the requirements of section 4.1.3 of 'Planning for\nBush Fire Protection 2006'.\nAccess\nThe intent of measures for public roads is to provide safe operational access to structures and\nwater supply for emergency services, while residents are seeking to evacuate from an area. To\nachieve this, the following conditions shall apply:\n4. Public road access shall comply with section 4.1.3 (1) of ‘Planning for Bush Fire Protection 2006’.\nThe intent of measures for property access is to provide safe access to/from the public road system\nfor fire fighters providing property protection during a bush fire and for occupants faced with\nevacuation. To achieve this, the following conditions shall apply:\n5. The property access road shall comply with section 4.1.3 (2) of Planning for Bush Fire Protection\n2006.\nDesign and Construction\nThe intent of measures is that buildings are designed and constructed to withstand the potential\nimpacts of bush fire attack. To achieve this, the following conditions shall apply:\n6. The Northern and Eastern elevations including all balcony’s and roof structures shall comply\nwith section 3 and section 6 (BAL 19) Australian Standard AS3959-2009 ‘Construction of buildings\nin bush fire-prone area’ or NASH Standard (1.7.14 updated) ‘National Standard Steel Framed\nConstruction in Bushfire Areas - 2014’ as appropriate and section A3.7 Addendum Appendix 3 of\n'Planning for Bush Fire Protection' 2006’.\n7. The Southern and Western elevations shall comply with Sections 3 and 5 (BAL 12.5) Australian\nStandard AS3959-2009 'Construction of buildings in bush fire-prone areas' or NASH Standard\n(1.7.14 updated) ‘National Standard Steel Framed Construction in Bushfire Areas - 2014’ as\nappropriate and section A3.7 Addendum Appendix 3 of 'Planning for Bush Fire Protection 2006'.\nLandscaping\n8. Landscaping to the site is to comply with the principles of Appendix 5 of “Planning for Bush Fire\nProtection 2006”.\n1.4. Comply with all commitments listed in BASIX Certificate as required under clause 97A of the\nEnvironmental Planning and Assessment Regulation 2000.\n2.. PRIOR TO ISSUE OF ANY CONSTRUCTION CERTIFICATE\n2.1. All conditions under this se ction must be met prior to the issue of any Construction Certificate.\n2.2. No activity is to be carried out on-site until the Construction Certificate has been issued, other than:\na) Site investigation for the preparation of the construction, and / or\nb) Implementation of environmental protection measures, such as erosion control and the like that\nare required by this consent\nc) Demolition approved by this consent.\n2.3. Special Infrastructure Contribution - Gosford City Centre - Obtain a determination by the Planning\nSecretary as to whether a special infrastructure contribution i s required to be made under the\nEnvironmental Planning and Assessment (Special In frastructure Contribution - Gosford City Centre)\nDetermination 2018 (2018 Determination). The developer must do so before the time by which a special\ninfrastructure contribution, if made as a monetary contribution , would have to be paid under the 2018\nDetermination.\nTo assist the Planning Secretary in making that determination, the developer is to provide the Planning\nSecretary with an up-to-date estimate of the proposed cost of carrying out the development, as referred\nto in the 2018 Determination.\nIf the Planning Secretary determines that a special infrastruct ure contribution is required to be made\nunder the 2018 Determination, a contribution must be made in accordance with that Determination (as\nin force when this consent takes effect).\nA perso n ma y no t apply f or a co ns truc tion cer tificat e in relation to development the subject of this\ndevelopment consent unless the pe rson provides, in connection with the application, written evidence\nfrom the Department of Planning and Environment that the specia l infrastructure contribution for the\ndevelopment (or that part of the development for which the certificate is sought) has been made or that\narrangements are in force with respect to the making of the contribution.\nIn this condition:\ndeveloper means the person having the benefit of this development consent, and\nPlanning Secretary means the Secretary of the Department of Planning and Environment.\nMore information - Please contact the Department of Planning an d Environment by email to:\nSIContributions@planning.nsw.gov.au\n2.4. Pay to Council a contribu tion amount of $282,320 that may require adjustment at time of payment, in\naccordance with the Section 94A Development Contribution Plan - Gosford City Centre.\nThe total amount to be paid must be indexed each quarter in accordance with the Consumer Price Index\n(All Groups index) for Sydney issued by the Australian Statistician as outlined in the contribution plan.\nContact Council’s Contributions Planner on Tel 1300 463 954 for an up-to-date contribution payment\namount.\nAny Construction Certificate must not be issued until the developer has provided the Accredited Certifier\nwith a copy of a receipt issued by Council that verifies that the contributions have been paid. A copy of\nthis receipt must accompany the documents submitted by the cert ifying authority to Council under\nClause 104/Clause 160(2) of the Environmental Planning and Assessment Regulation 2000.\nA copy of the Contributions Plan may be inspected at the office of Central Coast Council, 49 Mann Street\nGosford or on Council’s website: Development Contributions - former Gosford LGA\n2.5. Submit an application to C ouncil under Section 305 of the Water Management Act 2000 to obtain a\nSection 307 Certificate of Compliance. The Application for a 307 Certificate under Section 305 Water\nManagement Act 2000 form can be found on Council’s website www.centralcoast.nsw.gov.au. Early\napplication is recommended.\nA Section 307 Certificate must be obtained prior to the issue of any Construction Certificate.\n2.6. Obtain a Roads Act Works Approval by submitting an applica tion to Council for a Section 138 Roads Act\nWorks Approval for all works required within the road reserve. The application is to be lodged using an\nApplication for Subdivision Works Ce rtificate or Construction Certificate, Roads Act Works Approval and\nother Development related Civil Works form.\nThe application is to be accompan ied by detailed design drawing s, reports and other documentation\nprepared by a suitably experienced qualified professional in ac cordance with Council’s Civil Works\nSpecifications.\nFees, in accordance with Council’s Fees and Charges, will be in voiced to the applicant following\nlodgement of the application. Fees must be paid prior to Counci l commencing assessment of the\napplication.\nDesign drawings, reports and documentation will be required to address the following works within the\nroad reserve:\na) Half width road works including kerb and guttering, subsoil dra inage, footpath formation,\ndrainage and a minimum 6m wide road pavement across the full frontage of the site in Bent\nStreet.\nb) Footway formation graded at +2% from the top of kerb to the property boundary, across the full\nfrontage of the site in Bent Street.\nc) Road works in Gertrude Street inc luding kerb and guttering (both sides), subsoil drainage, 1m\nwide footway formation graded at 2% on the eastern side, 3m wide footway formation graded at\n2% on the western side, drainage, and a minimum 6m wide road pa vement across the frontage\nof the site in Gertrude Street associated with the service road.\nd) Intersection of Bent Street & Ge rtrude Street to provide a turn ing head for the waste services\nvehicle and the NSW RFS emergency vehicle to enter and exit Bent Street in a forward direction.\nThe intersection shall be design ed to accommodate the manoeuvra bility for the AS2890.2:2002\n12.5m Heavy Rigid Vehicle (HRV), and facilitate the AS2890.2:2002 12.5m HRV to reverse into the\nservice road within the Gertrude Street frontage of the site. The footway formation on the northern\nside of the intersection works shall be provided to accommodate a guard rail in a location that\nwill not conflict with the overhang of the AS2890.2:2002 12.5m HRV.\ne) 1.5m wide reinforced (SL72 steel fabric, 100mm thick) concrete footpath in an approved location\nacross the full frontage of the site in Bent Street.\nf) 3m wide reinforced (SL72 steel fabric, 100mm thick) concrete footpath on the western side of the\nroad pavement works in Gertrude Street associated with the service road.\ng) 1m wide reinforced (SL72 steel fabric, 100mm thick) concrete footpath on the eastern side of the\nroad pavement works Gertrude Street associated with the service road and the eastern side of the\npavement works associated with the intersection of Bent Street and Gertrude Street.\nh) Heavy-duty vehicle crossing in Gertrude Street associated with access to the bin holding area that\nhas a width of 5.5m and constructed with 200mm thick concrete r einforced with 1 layer of SL72\nsteel fabric top and bottom.\ni) Retaining walls around the southern and eastern sides of the proposed works within the Gertrude\nStreet road reserve (including the service road and intersectio n works). Retaining walls must be\ndesigned by a practising Civil / Structural engineer in conjunction with the recommendations from\na practising Geotechnical engin eer. Retaining walls must not co nflict with services. Note: The\nworks shall include all excavated batter slopes and necessary s tabilization works within the\nunformed section of Gertrude Stre et (Asset Protection Zone). T he design is to be certified by a\nregistered practising Civil or St ructural engineer as being in accordance with the relevant\nAustralian Standards.\nj) A concrete catch drain on the high (eastern) side of the retaining walls within the Gertrude Street\nroad reserve (including the service road and intersection works), with a minimum depth of 300mm\nand to connect to the proposed dr ainage pit within the northern e n d o f t h e t u r n i n g h e a d i n\nGertrude Street.\nk) A safety fence (chain wire) with a minimum height of 1.8m on the high side of the retaining walls\naround the southern and eastern sides of the proposed works wit hin the Gertrude Street road\nreserve (including the service road and intersection works).\nl) all redundant vehicular crossings are to be removed and footway formation reinstated.\nm) Connection of stormwater from the turning head at the intersection of Bent Street and Gertrude\nStreet, and the service road and associated catch drain in Gert rude to the existing watercourse\nwithin the Gertrude Street road reserve on the northern side of the proposed turning head works.\nn) The piping of stormwater from wi thin the site to Council’s exis ting piped drainage system in\nFaunce Street.\no) Longitudinal street drainage (min imum 375mm RCP) along the nort hern side of Faunce Street\nfrom where the proposed drainage pipeline from the development meets the kerb alignment in\nFaunce Street to connect to the existing drainage pit on the northern side of Faunce Street located\nnear the intersection on Faunce Street and Watt Street. This will require new kerb inlet pits at the\ns t a r t o f t h e p i p e l i n e , r e c o n s t r u c t i o n o f t h e e x i s t i n g k e r b i n l et pit associated with the pipeline\nconnection of SP 91805 (No 19 Watt Street) to Faunce Street, reconstruction of the existing kerb\ninlet pit in Faunce Street near the intersection of Faunce Street and Watt Street, and new pipelines\nto suit.\np) Roadside furniture and safety dev ices as required eg. fencing, signage, guide posts, chevrons,\nand/or guard rail in accordance with RMS and relevant Australian Standards\nq) “No Parking’ signage within the s ervice road within the Gertrud e Street frontage of the site, the\nturning head at the intersection of Bent Street and Gertrude Street, and within the eastern end of\nBent Street to ensure that the swept turning paths of the AS289 0.2:2002 12.5m HRV are\nunobstructed at all times. The signage and line marking plan must be approved by Council’s Traffic\nCommittee.\nr) Erosion and sedimentation control plan.\nThe design of the required works shall be generally in accordan ce with the plans prepared by Barker\nRyan Stewart, Reference CC150124E2-G, Sheets 1-8, & 17-19, all Rev G dated 2/04/2019.\nThe section 138 Roads Act Works Approval must be issued by Council and all conditions of that approval\nmust be addressed prior to occupying and commencing any works in the road reserve.\n2.7. Submit to Council a dilapidation report detailing the cond ition of all Council assets within the vicinity\nof the development. The report must document and provide photographs that clearly depict any\nexisting damage to the road, kerb, gutter, footpath, driveways, street trees, street signs, street lights or\nany other Council assets in the vicinity of the development. The dilapidation report will be required to\nbe submitted to Council prior to the issue of the Section 138 Roads Act Works approval or the issue of\nany construction certificate for works on the site. The dilapidation report may be updated with the\napproval of Council prior to the commencement of works. The report will be used by Council to\nestablish damage to Council’s assets resulting from the development works.\n2.8 Submit to the Accredited Cert ifier responsible for issuing the construction certificate for works within\nthe development site detailed design drawings and design reports for the following engineering works:\na) driveways / ramp s and car parking areas must be designed accord ing to the requirements of\nAustralian Standard AS 2890: Parking Facilities for the geometric designs, and industry Standards\nfor pavement designs.\nb) a stormwater detention system mu st be designed in accordance wi th Chapter 6.7 - Water Cycle\nManagement o f t h e G o s f o r d D e v e l o p m e n t C o n t r o l P l a n 2 0 1 3 a n d C o u n c i l ’ s Civil Works\nSpecification. The stormwater detention system must limit post development f lows from the\nproposed development to less than or equal to predevelopment fl ows for all storms up to and\nincluding the 1% Annual Exceedance Probability (AEP) storm event. A runoff routing method must\nbe used. An on-site stormwater detention report including an op eration and maintenance plan\nmust accompany the design. On-site stormwater detention is not permitted within private\ncourtyards, drainage easements, and / or secondary flow paths. On-site detention is to be\ndesigned generally in accordance with the Stormwater Management Report prepared by Barker\nRyan Stewart Project No CC150124 Rev 4 dated 20/11/19).\nc)\nnutrient/pollution control measu res must be designed in accorda nce with Chapter 6.7 - Water\nCycle Management of the Gosford Development Control Plan 2013. A nutrient / pollution control\nreport including an operation an d maintenance plan must accompa ny the design.\nNutrient/pollution controls are to be designed generally in acc ordance with the Stormwater\nManagement Report prepared by Bar k e r R y a n S t e w a r t P r o j e c t N o C C150124 Rev 4 dated\n20/11/19).\nd) on-site stormwater retention measures must be designed in accordance with Chapter 6.7 - Water\nCycle Management of the Gosford Development Control Plan 2013. A report detailing the method\nof stormwater harvesting, sizing of retention tanks for re-use on the site and an operation and\nmaintenance plan must accompany the design. On-site retention m easures are to be designed\ngenerally in accordance with the Stormwater Mana gement Report p repared by Barker Ryan\nStewart Project No CC150124 Rev 4 dated 20/11/19).\ne) interallotment drainage within Lot 27 Sec 6 DP 1591, Lot 28 Sec 6 DP 1591, & Lot B DP 338871 to\nconnect stormwater from the devel opment to Council’s drainage s ystem in Faunce Street. The\ninterallotment drainage system m ust be designed in accordance w ith Council’s Civil Works\nSpecification and have a minimum capacity to accommodate the stormwater flows associated with\nthe site in the 1%AEP storm even t. The interallotment drainage system shall be generally in\naccordance with the plan prepared by Barker Ryan Stewart, Plan No CC150124E1.19 Rev G dated\n2/04/2019.\nf) piping of all stormwater from impervious areas within the site to the required interallotment\ndrainage system to then connect to Council’s drainage system located in Faunce Street.\nDetailed design drawings and design reports acceptable to the Accredited Certifier must be included in\nthe Construction Certificate documentation.\n2.9 Submit a pavement investigat ion and report prepared by a practising Geotechnical Engineer for the\nroad works. This report must be submitted with the application for work under the Roads Act 1993.\nThe pavement depths must be determined in accordance with Council’s specifications and the\nfollowing traffic loadings:\nName of Street Traffi c Loading (ESAs)\nBent Street 2 x 10\n6 Gertrude Street 2 x 10 6\nGertrude St / Bent St Turning Head & Intersection 2 x 10 6\n2.10 Submit engineering details p repared and certified by a practising structural engineer that comply with\nCouncil’s Building Over or Adjacent To Sewer and Water Main Guidelines to the satisfaction of Council.\nEngineering details must be submitted to Council’s Water Assessment Team for approval. Plan\nassessment fees apply.\n2.11 Pay a security deposit of $100,000 into Council’s trust fu nd. The payment of the security deposit is\nrequired to cover the cost of repairing damage to Council's assets that may be caused as a result of the\ndevelopment. The security deposit will be refunded upon the com pletion of the project if no damage\nwas caused to Council's assets as a result of the development.\n2.12 Submit to Council’s Environm ent Officer for approval, a Soil and Water Management Plan in accordance\nwith Section 6.3 of the Gosford Development Control Plan 2013 a nd the ‘Blue Book’ (Managing Urban\nStormwater: Soils and Construction, Landcom, 2004). The plan shall be prepared by a suitably qualified\nenvironmental/civil consultant and shall be adaptive to address all stages of the construction.\n2.13 Submit to Council, the Accredited Certifier and relevant a djoining property owners a dilapidation report,\nprepared by a practising structural engineer, detailing the str uctural characteristics of all buildings\nlocated on No. 5 Bent Street and No’s 142 and 144 Faunce Street. The report must document and provide\np h o t o g r a p h s t h a t c l e a r l y d e p i c t a n y e x i s t i n g d a m a g e t o t h e i m p rovements erected upon allotments\nimmediately adjoining the develop ment site and to the road, ker b, footpath, drivew ays, water supply\nand sewer infrastructure, street trees and street signs or any other Council asset in the vicinity of the\ndevelopment.\nIn the event that access to an adjoining property(s) for the pu rpose of undertaking the dilapidation\nreport is denied, the applicant must demonstrate in writing that all steps were taken to obtain access to\nthe adjoining property(s).\n2.14 Submit amendments to the approved plans and reports to the accredited certifier pursuant to Clause\n139 of the Environmental Planning Regulation 2000: App lications for construction certificates that must\ndetail:\na. Mail boxes:\ni. Provide mail boxes for each residential building in one accessible location adjacent to the\nmain entrance to the development;\nii. They should be integrated into a wall where possible and be con structed of materials\nconsistent with the appearance of the building;\niii. Mail boxes shall be secure and large enough to accommodate articles such as newspapers;\nb. Locate satellite dish and telec ommunication antennae, air condi tioning units, ventilation stacks\nand any ancillary structures:\ni. Away from the street frontage;\nii. Integrated into the roof-scape design and in a position where such facilities will not become\na skyline feature at the top of any building;\niii. Adequately setback from the perimeter wall or roof edge of buildings;\nc. A master antenna must be provi ded for residential apartment bui ldings. This antenna shall be\nsited to minimise its visibility from surrounding public areas;\nd. The reflectivity index (expressed as a percentum of the reflected light falling upon any surface) of\ne x t e r n a l g l a z i n g f o r w i n d o w s , w a l l s o r r o o f f i n i s h e s o f t h e p r oposed development is to be no\ngreater than 20%;\ne. Storage areas are to be provided in accordance with the following minimum rates:\ni. 6m³ for studio and one bedroom units;\nii. 8m³ for two bedroom units;\niii. 10m³ for three pl us bedroom units; and\nAt least 50% of the required storage areas are to be provided within each dwelling.\nf. A minimum of one (1) loading /servicing bay is to be provided on Basement Level 1, nearby the lift\naccess.\ng. The external colour schedule of the development must be consist en t wit h t he extern al mat erial,\nfinishes and colours on DA 21(F) and DA22(F) and photomontage r eferenced as supporting\ndocumentation in Condition 1.1 of this Consent.\n2.15 The recommendations of the Noise Assessment, prepared by Spectrum Acoustics, dated 1 February\n2016, must be included in the Construction Certificate, including, but not limited to:\na. all windows with a direct view of Henry Parry Drive should be u pgraded to 6.5mm Vlam Hush\nlaminated glazing or equivalent.\n3.. PRIOR TO COMMENCEMENT OF ANY WORKS\n3.1. All conditions under this se ction must be met prior to the commencement of any works.\n3.2. Appoint a Principal Certifying Authority for the building work.\na) The Principal Certifying Authority (if not Council) is to notif y Council of their appointment and\nnotify the person having the benefit of the development consent of any critical stage inspections\nand other inspections that are to be carried out in respect of the building work no later than two\n(2) days before the building work commences.\nb) Submit to Council a Notice of Commencement of Building Works or Notice of Commencement of\nSubdivision Works form giving at least two (2) days notice of the intention to commence building\nor subdivision work. The forms can be found on Council’s website www.gosford.nsw.gov.au\n3.3. Provide and maintain a garba ge receptacle at the work site until the works are completed. The garbage\nreceptacle must have a tight fitting lid and be suitable for food scraps and papers.\n3.4. Install run-off and erosion controls to prevent soil erosi on, water pollution or the discharge of loose\nsediment on the surrounding land by:\n erecting a silt fence and providi n g a n y o t h e r n e c e s s a r y s e d i m e nt control measures that will\nprevent debris escaping into drainage systems, waterways or adjoining properties, and\n diverting uncontaminated run-off around cleared or disturbed areas, and\n preventing the tracking of sediment by vehicles onto roads, and\n stockpiling top soil, excavated materials, construction and landscaping supplies and debris within\nthe lot.\nDo not commence site works until the sediment control measures have been installed in accordance\nwith the approved plans / Gosford DCP 2013 Chapter 6.3 - Erosion Sedimentation and Control.\n3.5. Notify the intention to commence works by giving written n otice to the owner of the adjoining property\naffected by the proposed excavati on and/or structural protectiv e works. The required notice must be\naccompanied by details of the pr oposed work at least seven (7) days prior to the commencement of\nproposed excavation and/or structural protection works.\n3.6. Disconnect, seal and make s afe all existing site services prior to the commencement of any demolition\non the site. Sewer and water services must be disconnected by a licensed plumber and drainer with a\nStart Work Docket submitted to C ouncil's Plumbing and Drainage Inspector as the Water and Sewer\nAuthority.\n3.7. Provide certification to the Principal Certifying Authorit y that the structural engineer's details have been\nprepared in accordance with the re commendations of the geotechn ical report(s) listed as supporting\ndocumentation in this development consent.\n3.8. Submit a dilapidation repor t to Council with the Roads Act application and / or Construction Certificate\napplication. The report must document and provide photographs that clearly depict any existing\ndamage to the road, kerb, gutter, footpath, driveways, street trees, street signs or any other Council\nassets in the vicinity of the development. The dilapidation report may be updated with the approval of\nthe Principal Certifying Authority prior to the commencement of works.\n3.9. Erect a sign in a prominent position on any work site on w hich building, subdivision or demolition\nwork is being carried out. The sign must indicate:\na) The name, address and telephone number of the Principal Certifying Authority for the work; and\nb) The name of the principal contractor and a telephone number at which that person can be\ncontacted outside of working hours; and\nc) That unauthorised entry to the work site is prohibited.\nd) Remove the sign when the work has been completed.\n3.10. Submit both a Plumbing an d Drainage Inspection Application, with the relevant fee, and a Plumbing\nand Drainage Notice of Work in accordance with the Plumbing and Drainage Act 2011 (to be provided\nby licensed plumber). These documents can be found on Council’s website at:\nwww.gosford.nsw.gov.au.\nContact Council prior to submitting these forms to confirm the relevant fees.\n3.11. Provide toilet facilities at a ratio of one toilet plus o ne additional toilet for every 20 persons employed\nat the site. Each toilet must:\na. Be a standard flushing toilet connected to a public sewer, or\nb. Have an on-site effluent disposal system approved under the Local Government Act 1993, or\nc. Be a temporary closet approved under the Local Government Act 1993\n3 . 1 2 . P r e v e n t p u b l i c a c c e s s t o t h e c o n s t r u c t i o n s i t e a s r e q u i r ed by Clause 298 of the Work Health and\nSafety Regulation 2011 when building work is not in progress or the site is unoccupied . Site fencing\nspecifications are outlined under Australian Standard AS1725.1- 2010 - Chain-link fabric fencing -\nSecurity fencing and gates. The use of barbed wire and/or el ectric fencing is not to form p art of the\nprotective fencing to construction sites.\nA separate application made under the Roads Act 1993 will need to be lodged with Council If a hoarding\nor construction site fence must be erected on the road reserve or a public place.\n3.13. Disconnect and ca p the property’s sewer at the inspection shaft.\n3.14. Undertake demolition involv ing asbestos in accordance with the Work Health and Safety Act 2011.\nThe person having the benefit of this consent must ensure that the removal of:\na. more than 10m2 of non-friable asbestos or asbestos containing material is carried out by a licensed\nnon-friable (Class B) or a friable (Class A) asbestos removalist, and\nb. friable asbestos of any quantity is removed by a licensed removalist with a friable (Class A) asbestos\nremoval licence.\nThe licensed asbestos removalist must give notice to the regula tor before work commences in\naccordance with Clause 466 of the Work Health and Safety Regulation 2011.\n3.15. Prepare a Construction Tra ffic and Pedestrian Management Plan (CTPMP) for all ac tivities related to\nworks within the site. The plan must be prepared and implemente d only by persons with Roads and\nMaritime Service accreditation for preparing and implementing traffic management plans at work sites.\nThe CTPMP must describe the prop osed construction works, the tr affic impacts on the local area and\nhow these impacts will be addressed.\nThe CTPMP must address, but not be limited to, the following matters:\n Ingress and egress of construction related vehicles to the development site.\n Details of the various vehicle lengths that will be used during construction and the frequency of\nthese movement.\n Use of swept path diagrams to demonstrate how heavy vehicles enter, circulate and exit the site\nor Works Zone in a forward direction.\n Deliveries to the site, including loading / unloading materials and requirements for work zones\nalong the road frontage to the development site. A Plan is to b e included that shows where\nvehicles stand to load and unload, where construction plant wil l stand, location of storage areas\nfor equipment, materials and waste, locations of Work Zones (if required) and location of cranes\n(if required).\n Works Zones if heavy vehicles cannot enter or exit the site in a forward direction.\n Control of pedestrian and vehicular traffic where pre-construction routes are affected.\n Temporary Road Closures.\nWhere the plan identifies that th e travel paths of pedestrians and vehicular traffic are proposed to be\ninterrupted or diverted for any construction activity related t o works inside the development site an\napplication must be made to Council for a Road Occupancy Licenc e. Implementation of traffic\nmanagement plans that address inte rruption or diversion of pede strian and/or vehicular traffic must\nonly take place following receipt of a Road Occupancy Licence from Council or the Roads and Maritime\nService where on a classified road.\nWhere a dedicated delivery vehicle loading and unloading zone is required along the road frontage of\nthe development site a Works Zone Application must be lodged and approved by Council. A minimum\nof 3 months is required to allow Traffic Committee endorsement and Council approval.\nThe Construc tion Traffic and Pedestria n Management Plan must be reviewed and updated during\nconstruction of the development to address any changing site conditions.\nA copy of the Construction Tra ffic and Pedestrian Management Pl an must be held on site at all times\nand be made available to Council upon request.\n3.16. Submit to Council, for approval, details of proposed haul age routes to and from the site. Approval of\nhaulage routes may be subject to the provision of a dilapidation report of all or part of the approved\nhaulage route.\n3.17. Ensure that all parties / trades working on the site are fully aware of their responsibilities with respect\nto tree protection conditions.\n3.18. Tree Protection is to be as per the recommendations of th e Arboricultural Impact Assessment by R\nKingdom 19/11/18.\n3.19. A site meeting is to be held prior to works between the bushfire consultant and project ecologist to\ndetermine the locations and quantities of native vegetation islands within the APZ. The potential\nimpacts will be mitigated by the maximum retention of vegetation as allowed under bushfire rules. To\nmaintain ecological connectivity, islands of native vegetation are to be retained within the APZ. This is\nachieved by restricting the removal of native vegetation and by relocating native understorey species\nthat are characteristic of Narrabeen Coastal Blackbutt Forest (e.g. Themeda australis Kangaroo grass)\nto replace weed species within those islands. The Arboriculture Report and Landscape Plan is to be\namended and submitted to Council Ecologist for approval.\n3.20. Tree Qualified ecologist to attend the site no more than 3 weeks prior clearing. The ecologist must:\n Mark trees for retention and removal\n Supervise the installation of fencing around any conservation areas\n Provide an environmental induction to civil contractors and subcontractors\n Provide a nest box replacement s trategy (hollow bearing tree in spection, monitoring and\nmanagement of fauna prior to clearing, replacement box locations).\n Provide a written report to be to Councils Ecologist with the f ocus of Wildlife/ habitat\nManagement for the replacement hollow bearing trees.\n3.21. A detailed Maintenance Plan of the APZ in accordance with RFS requirements and Inner Protection Area\n(IPA) as outlined within section 4.1.3 and Appendix 5 of 'Planning for Bush Fire Protection 2006' and the\nN S W R u r a l F i r e S e r v i c e ' s d o c u m e n t ' S t a n d a r d s f o r a s s e t p r o t e c t ion zones’ in accordance with the\nArboriculture Report and Landscape Plan as amended by Condition 3.19 above shall be submitted to\nthe PCA prior to the issue of a Construction Certificate. The m aintenance plan shall be prepared by a\nsuitably qualified person and include details on regularly scheduled checks and maintenance, responses\nto weather and incidents as deemed appropriate as well as detailing responsible parties for the ongoing\nmaintenance.\nThe PCA, if not Council, shall forward a copy of the approved plans and maintenance schedule to Council.\n3.22 The interallotment drainage pipeline and required drainage works within Faunce Street are be\nconstructed and operational prior to commencement of building works on the site.\n4.. DURING WORKS\n4.1. All conditions under this section must be met during works .\n4.2. Carry out construction or demolition works during the cons truction phase of the development only\nbetween the hours as follows:\n 7.00am and 5.00pm Monday to Saturday\nNo construction or demolition works associated with the development are permitted to be carried out\nat any time on a Sunday or a public holiday.\n4.3. During the construction pha se of the development, if any Aboriginal object (including evidence of\nhabitation or remains), is discovered during the course of the work:\na) All excavation or disturbance of the area must stop immediately in that area, and\nb) The Office of Environment and He ritag e m us t be ad vised of t he discovery in accordance with\nsection 89A of the National Parks and Wildlife Act 1974.\nNote: If an Aboriginal object is discovered, an Aboriginal heritage impact permit may be required\nunder the National Parks and Wildlife Act 1974.\n4.4. Implement and maintain all erosion and sediment control at or above design capacity for the duration\nof the construction works and until such time as all ground disturbed by the works has been stabilised\nand rehabilitated so that it no longer acts as a source of sediment. The controls must comply with\nCouncil's Code of Practice of Erosion and Sedimentation Control.\n4.5. Keep a copy of the stamped approved plans on-site for the duration of site works and make the plans\navailable upon request to either the Principal Certifying Authority or an officer of Council.\n4.6. Demolish buildings in a safe and systematic manner in acco rdance with AS2601-2001: The demolition of\nstructures. Waste materials must be disposed of at a waste management facility.\n4.7. Notify Council when plumb ing and drainage work will be ready for inspection(s) and make the work\naccessible for inspection in accordance with the Plumbing and Drainage Act 2011.\nThis condition only applies if installation / alteration of plumbing and / or drainage works are\nproposed (excludes stormwater drainage).\n4.8. Place all building materials, plant and equipment on the s ite of the development during the\nconstruction phase of the development so as to ensure that pedestrian and vehicular access within\nadjoining public roads, footpaths and reserve areas, is not restricted and to prevent damage to public\ninfrastructure. Further, no construction work is permitted to be carried out within the road reserve\nunless the works are associated with a separate approval issued under the provisions of the Roads Act\n1993.\n4.9. Action the following when an excavation extends below the level of the base of the footings of any\nbuilding, structure or work on adjoining land:\na. notify the owner of the adjoining land, and\nb. protect and support the building, structure or work from possible damage from the excavation, and\nc. underpin the building, structure or work where necessary, to prevent any such damage.\nThese actions must be undertaken by the person having the benefit of the development consent at their\nown expense.\n4.10. Re-use, recycle or dispos e of all building materials during the demolition and construction phase of the\ndevelopment in accordance with the Waste Management Plan signed by Barker Ryan Stewart, dated 5\nMay 2020.\n4 . 1 1 . T h e p r o p o s e d t u r n i n g h e a d / w a s t e v e h i c l e s e r v i c i n g a c c e s s road to be construct ed out of reinforced\nconcrete and be capable of withstanding a truck loading of 22.5 tonnes.\n4.12. Undertake the removal of any tree located on Council managed land due to works approved by a\nDevelopment Application at the full cost and responsibility of the developer / owner using a Pre-\nqualified Tree Contractor.\nContact Central Coast Council on 1300 463 954 for the current list of relevant contractors.\n4.13. Undertake the removal of trees as shown on the approved plans in a manner so as to prevent damage\nto those trees that are to be retained.\n4.14. Remove trees and ground stum ps in a manner so as to not damage trees to be retained.\n4.15. Suppress dust with th e use of a water cart.\n4.16. Fill material must only comprise of Virgin Excavated Natu ral Material (VENM) or Excavated Natural\nMaterial (ENM).\nVirgin Excavated Natural Materi al (VENM) is defined under Sched ule 1 of the Protection of the\nEnvironment Operations (POEO) Act 1997 as follows:\n\"virgin excavated natural material\" means natural material (such as clay, gravel, sand, soil or roc k\nfines):\n(a) t h a t h a s b e e n e x c a v a t e d o r q u a r r i e d f r o m a r e a s t h a t a r e n o t c o ntaminated with\nmanufactured chemicals, or with process residues, as a result o f industrial, commercial,\nmining or agricultural activities, and\n(b) that does not contain any sulfidic ores or soils or any other waste,\nExcavated Natural Material (ENM) that has been issued with an e xemption under the Protection\nof the Environment Operations (Waste) Regulation 2014 in accordance with the Excavated Natural\nMaterial Order and Exemption 2014.\nThe placement of any other type of fill material other than that defined under VENM or ENM is prohibited\nunder this consent.\nThe applicant must provide Council with validation documents verifying and certifying that the material\nplaced on the land complies with:\n\nthe definition of VENM under Schedule 1 of the POEO Act 1997, or\n an exemption issued under the Excavated Natural Material Order and Exemption 2014.\nAny exposed soil surface areas must be grassed / landscaped to minimise soil erosion.\n4.17. No fill other than as show n on the approved plans is permitted.\n4.18. Submit a report prepared by a registered Surveyor to the Principal Certifying Authority at each floor level\nof construction of the building (prior to the pouring of concrete) indicating that the finished floor level\nis in accordance with the approved plans.\n4.19. Implement all recommendations of the geotechnical report( s) listed as supporting documentation in this\ndevelopment consent. Furthermore, the geotechnical engineer must provide written certification to the\nPrincipal Certifying Authority that all works have been carried out in accordance with the\nrecommendations contained within the geotechnical report(s).\n4.20. Incorporate the following Crime Prevention Through Enviro nmental Design (CPTED) principles and\nstrategies to minimize the opportunity for crime:\na. Provide adequate lighting to common areas as required under AS1158: Lighting for roads and public\nspaces.\nb. Paint the ceiling of the car park white.\nc. Design of landscaping, adjacent t o m a i l b o x e s a n d f o o t p a t h s , m u st not provide concealment\nopportunities for criminal activity.\nd. Design the development to avoid foot holes or natural ladders so as to minimise unlawful access to\nthe premises.\ne. Provide signage within the development to identify all faciliti es, entry/exit points and direct\nmovement within the development.\n4.21. Erect or install prior to the swimming pool being filled with water all the required swimming pool safety\nbarriers and gates in accordance with the approved plans and sp ecifications and the provisions of the\nSwimming Pools Act 1992 , Swimming Pools Regulations 2018 and Australian Standard AS 1926.1-2012\nincluding the display of an approved sign regarding pool safety and resuscitation techniques that\ncontains all of the following information:\n(i) “Young children should be actively supervised when using this swimming pool”, and\n(ii) “Pool gates must be kept closed at all times”, and\n(iii) “Keep articles, objects and structures clear of the pool fence at all times”,\nA simple flow sequence (which may be the flow sequence depicted in the Cardiopulmonary Resuscitation\nGuideline) containing details of resuscitation techniques (for infants, children and adults)\n4.22. Do not fill the swimming p ool with water until a boundary fence forming part of the pool enclosure has\nbeen installed with a minimum hei ght of 1.8 metres when measure d inside the pool enclosure in\naccordance with the provisions o f Australian Standard AS 1926.1 2012. The maintenance and\neffectiveness of the fence is the responsibility of the pool ow ner whilst ever the pool exists. The fence\nis to provide separation of the swimming pool and the gym room, with no gym equipment permitted\nwithin the fenced enclosure.\nA l t e r n a t i v e l y , t h e p o o l m u s t b e f u l l y e n c l o s e d b y s w i m m i n g p o o l safety fencing complying with the\nprovisions of Australian Standard AS 1926.1-2012 in lieu of any boundary fencing.\n4.23. Dispose filter backwash and overflow to the sewer. The se wer connection must be completed prior to\nthe filling of the pool with water and in a manner that will no t cause a nuisance, or where sewer is not\navailable, the disposal of filter backwash must be discharged i nto a rubble absorption trench to the\nsatisfaction of the Principal Certifying Authority.\n4.24. Do not fill the swimming pool with water until each windo w which is capable of giving access to the\ns w i m m i n g p o o l e n c l o s u r e h a s b e e n p r o t e c t e d w i t h s u i t a b l e s e c u r it y s c r e e n s c o m p l y i n g w i t h t h e\nprovisions of Clause 2.6 of Australian Standard AS 1926.1-2012. This applies to all windows where the\nheight of the sill of the lowest openable portion of the window is less than 1.8 metres above the adjoining\nground surface level.\n4.25. Supervision by a suitably qualified Ecologist is required for all vegetation clearing and construction\nworks. The Ecologist must:\n Mark trees for retention and removal\n Supervise the installation of fencing around any conservation areas\n Provide an environmental induction to civil contractors and subcontractors\n Supervise clearing, removal of habitat trees and earthworks\nThe Ecologist must provide update s in writing to Council’s Envi ronment Officer/Ecologist upon\ncompletion of the above environmental control measures.\n4.26 A minimum 4.0 m vertical hei ght clearance to be ensured in all waste vehicle manoeuvring area/s. No\nobstruction of this minimum clearance is permitted.\n4.27 The internal road strength t o be constructed to withstand a truck loading of 23.0 tonnes.\n5.. PRIOR TO ISSUE OF ANY OCCUPATION CERTIFICATE\n5.1. All conditions under this se ction must be met prior to the issue of any Occupation Certificate.\n5.2. Provide certification from a geotechnical engineer to the Principal Certifying Authority that all works\nhave been carried out in accordance with the recommendations co ntained within the geotechnical\nreport(s) listed as supporting documentation in this development consent. The certification shall include\nthe undertaken roadworks, excav ated batter slopes, retaining wa lls and stabilization works within the\nunformed section of Gertrude Street (Asset Protection Zone).\n5.3. Provide the Principal Certifying Authority with written ce rtification from a qualified landscape designer\ncertifying that landscaping has been implemented in accordance with the approved landscape plan as\namended by any conditions of this consent including condition 3.19.\n5.4. Provide to the Principal Certifying Authority a design ve rification statement from a qualified designer,\nbeing a statement in which the qualified designer verifies that the residential flat development achieves\nthe design quality of the development as shown in the plans and specifications in respect of which the\nConstruction Certificate was issued, having regard to the Desig n Quality Principles set out in Part 2 of\nState Environmental Planning Policy No 65 - Design Quality of Residential Flat Development.\n5.5. Consolidate LOT: 1 DP: 436706, Lot: 26 SEC: 6 DP: 1591 and Lot: B DP: 357731 into a single allotment\nunder one Certificate of Title.\nDocumentary evidence of the lo dgement of the Consolidation Plan with the NSW Land and Property\nInformation can be accepted by the Principal Certifying Authority as satisfying this requirement.\n5.6. Provide mail receptacles ap propriately numbered for each dwelling unit in the development, as well as\nfor the managing body, in consultation with Australia Post.\n5.7. Create and execute a docume ntary Public Positive Covenant under the Conveyancing Act 1919 t o\nestablish a positive covenant on the Certificate of Title detailing the areas to be maintained as an Asset\nProtection Zone as shown hatched on Plan Number DA 150124E1.02 R e v G ( d r a w n b y B a r k e r R y a n\nStewart) in accordance with the Bush Fire Report prepared by Advanced Bushfire Performance Solutions\ndated 13 December 2018. The restri ction must ensure the owner c o n t i n u a l l y m a i n t a i n s t h e A s s e t\nProtection Zone, including land in the adjacent Gertrude Street road reserve in accordance with the\nrecommendation and findings detailed in the Bush Fire Report an d the Arboriculture Report and\nLandscape Plan and modified by C ondition 3.19 and Maintenance P lan as required by Condition 3.21.\nThe restriction must be created at the applicants cost with Cou ncil having the sole authority to release\nor modify.\n5.8. With regard to the requirem ents of condition 5.7, a bylaw shall be registered with any future strata\nscheme, requiring that ongoing m aintenance of the Asset Protect ion Zone including the area of land\nwithin the unformed section of Gertrude Street (shown as hatched on Plan Number DA 150124E1.02 Rev\nG (drawn by Barker Ryan Stewart)) is carried out in accordance with the terms of the maintenance plan\nlodged with Council under condition 3.21. The terms of the byla w, shall be satisfactory to Council, and\nCouncil must be named as the authority with the right to release, vary or modify the bylaw\n5.9. Submit a Certificate of Compliance for all plumbing and dr ainage work and a Sewer Service Diagram\nshowing sanitary drainage work (to be provided by licensed plumber) in accordance with the Plumbing\nand Drainage Act 2011.\n5.10. Amend the deposited plan (DP) to include a Section 88B in strument under the Conveyancing Act 1919\nto indemnity Council against claims for loss or damage to the p avement or other driving surface and\nagainst liabilities, losses, damages and any other demands arising from any on-site collection service, at\nthe applicants cost.\n5.11. Parking restriction signage to be permanently fixed and prominently displayed to restrict other vehicles\nparking or stopping within the constructed roadway/accessway on residential waste collection days.\n5.12. Construct any additional civil works, where required by C ouncil, to ensure satisfactory transitions to\nexisting site formations and pavements where designs contained in the Roads Act Works Approval do\nnot adequately address transition works.\n5.13. Complete construction of the stormwater management system in accordance with the Stormwater\nManagement Plan and Australian Standard AS 3500.3-Stormwater drainage systems. Certification of\nthe construction by a suitably qualified consultant must be provided to the Principal Certifier.\n5.14. Complete construction of a ll works within the Bent and Gertrude Stree road reserve in accordance with\nthe Roads Act Works Approval. Completion of works includes the submission and acceptance by\nCouncil of all work as executed drawings plus other construction compliance documentation and\npayment of a maintenance/defects bond to Council in accordance with Council’s Fees and Charges.\n5.15. Repair any damage to Counc il’s infrastructure and road reserve as agreed with Council. Damage not\nshown in the dilapidation report submitted to Council before the development works had commenced\nwill be assumed to have been caused by the development works unless the Developer can prove\notherwise.\n5.16. Complete the civil engineer ing works within the development site in accordance with the detailed\ndesign drawings and design reports plans within the construction certificate.\n5.17. Amend the Deposited Plan (DP) for the site to:\n1)\nInclude an Instrument under the Conveyancing Act 1919 for the following restrictive covenants;\nwith Council having the benefit of these covenants and having s ole authority to release and\nmodify. Wherever possible, the extent of land affected by thes e covenants must be defined by\nbearings and distances shown on the plan. The plan and instrument must:\n C r e a t e a ‘ R e s t r i c t i o n o n t h e u s e o f L a n d ’ o v e r a l l l o t s c o n t a i ni n g a n o n - s i t e s t o r m w a t e r\ndetention system and / or a nutrient / pollution facility restricting any alteration to such facility\nor the erection of any structure over the facility or the place ment of any obstruction over the\nfacility.\n2) Include an instrument under the Conveyancing Act 1919 for the following positive covenants; with\nCouncil having the benefit of these covenants and having sole a uthority to release and modify.\nCovenant(s) required:\na) To ensure on any lot containing on-site stormwater detention system and / or a nutrient /\npollution facility that:\ni. the facility will remain in place and fully operational.\nii. the facility is maintained in accordance with the operational a nd maintenance\nplan so that it operates in a safe and efficient manner.\niii. Council’s officers are permitted to enter the land to inspect and repair the facility\nat the owner’s cost.\niv. Council is indemnified against all claims of compensation caused by the facility.\nNote: Standard wording, acceptable to Council, for covenants c an be obtained by contacting Council\nSubdivision Certificate Officer.\nSubmit to the Principal Certifier copies of registered title documents showing the restrictive and positive\ncovenants.\n5.18. Undertake works in accord ance with the approved Soil and Water Management Plan and update the\nplan as required during all stages of the construction.\n5.19 Submit to Council, the Accredited Certifier and relevant a djoining property owners a dilapidation\nreport post construction, prepared by a practising structural engineer, detailing the structural\ncharacteristics of all buildings located on No. 5 Bent Street and No’s 142 and 144 Faunce Street. The\nreport must document and provide photographs that clearly depict any existing damage to the\nimprovements erected upon allotments immediately adjoining the development site and to the road,\nkerb, footpath, driveways, water supply and sewer infrastructure, street trees and street signs or any\nother Council asset in the vicinity of the development.\n6.. ONGOING OPERATION\n6.1. Maintain the on-site detenti on and nutrient / pollution control facilities in accordance with the\noperation and maintenance plan.\n6.2. Implement the required Asset Protection Zone to the perimeter of the asset. The Asset Protection Zone\nmust be fuel managed so as to maintain fuel loadings as detailed within Planning for Bush Fire Protection\nGuidelines 2006 (NSW).\n6.3. Load and unload delivery vehicles wholly within the site. Delivery vehicles must enter and exit the site\nin a forward direction.\n6.4. Do not obstruct loading bays when not in use.\n6.5. Ensure the garbage / recycl ing bins do not encroach on the car parking or vehicle manoeuvring areas.\n6.6. Maintain the site landscaping for the life of the developm ent.\n6.7. No obstructions to the wheel out of the waste bins are permitted including grills, speed humps, barrier\nkerbs etc.\n6.8. Waste vehicle manoeuvring to be in accordance with the Tra ffic and Parking Assessment dated 13 May\n2020 by Barker Ryan Stewart.\n6.9. Place the mobile green waste containers at a suitable loca tion at the kerbside no earlier than the evening\nprior to the collection day and return to the approved waste storage enclosure as soon as possible after\nservice, no later than the evening on collection day. The residents, caretaker, owner, Owners Corporation\nare responsible for the placement and return of the mobile waste containers.\n6.10. Store all waste generated on the premises in a manner so that it does not pollute the environment.\n6.11. Comply with all commitments as detailed in the Waste Management Plan signed by Barker Ryan Stewart,\ndated 5 May 2020.\n6.12. Locate the approved waste st orage enclosure/area as indic ated on Project Number 15026, Drawing\nNumber DA08, Issue B dated 6 March 2020 prepared by ADG Architects\n6.13. Construct and manage the waste storage enclosure in accor dance with the provisions of Gosford DCP\n2013, Part 7: Chapter 7.2 - Waste Management, Appendix D and Appendix G, as applicable.\n6.14. Construct and manage garba ge chutes in accordance with the provisions of Gosford DCP 2013, Part 7:\nChapter 7.2 - Waste Management, Appendix F.\n6.15 Do not place or store waste material, waste product or was te packaging outside the approved waste\nstorage enclosure.\n6.16 Transport all waste generat ed on the premises to a facility which is licensed to receive that material.\n7. PENALTIES\nFailure to comply with this development consent and any condition of this consent may be a criminal offence.\nFailure to comply with other environmental laws may also be a criminal offence.\nWhere there is any breach Council may without any further warning:\n Issue Penalty Infringement Notices (On-the-spot fines);\n Issue notices and orders;\n Prosecute any person breaching this consent, and/or\n Seek injunctions/orders before the courts to retain and remedy any breach.\nWarnings as to Potential Maximum Penalties\nMaximum Penalties under NSW Environmental Laws include fines up to $1.1 Million and/or custodial\nsentences for serious offences.","stage":"general","stage_basis":"heading","page":5}]});
